describe('Modal with Tabbed Content - Remember Active Tab', () => {
  const modalSelector = '[data-testid="tabbed-modal"]';
  const tabButtonSelector = '[data-testid="tab-button"]';
  const tabPanelSelector = '[data-testid="tab-panel"]';
  const openModalButtonSelector = '[data-testid="open-modal-btn"]';
  const closeModalButtonSelector = '[data-testid="close-modal-btn"]';

  beforeEach(() => {
    cy.visit('/');
    cy.get(openModalButtonSelector).click();
    cy.get(modalSelector).should('be.visible');
  });

  it('should remember the active tab when modal is closed and reopened', () => {
    // Click on the second tab
    cy.get(tabButtonSelector).eq(1).click();
    cy.get(tabButtonSelector).eq(1).should('have.attr', 'aria-selected', 'true');

    // Verify the second tab panel is visible
    cy.get(tabPanelSelector).eq(1).should('be.visible');
    cy.get(tabPanelSelector).eq(1).should('have.attr', 'aria-hidden', 'false');

    // Close the modal
    cy.get(closeModalButtonSelector).click();
    cy.get(modalSelector).should('not.be.visible');

    // Reopen the modal
    cy.get(openModalButtonSelector).click();
    cy.get(modalSelector).should('be.visible');

    // Verify the second tab is still active
    cy.get(tabButtonSelector).eq(1).should('have.attr', 'aria-selected', 'true');
    cy.get(tabPanelSelector).eq(1).should('be.visible');
    cy.get(tabPanelSelector).eq(1).should('have.attr', 'aria-hidden', 'false');
  });

  it('should switch between tabs and persist the last active tab', () => {
    // Click on the third tab
    cy.get(tabButtonSelector).eq(2).click();
    cy.get(tabButtonSelector).eq(2).should('have.attr', 'aria-selected', 'true');
    cy.get(tabPanelSelector).eq(2).should('be.visible');

    // Switch to the first tab
    cy.get(tabButtonSelector).eq(0).click();
    cy.get(tabButtonSelector).eq(0).should('have.attr', 'aria-selected', 'true');
    cy.get(tabPanelSelector).eq(0).should('be.visible');

    // Switch back to the third tab
    cy.get(tabButtonSelector).eq(2).click();
    cy.get(tabButtonSelector).eq(2).should('have.attr', 'aria-selected', 'true');
    cy.get(tabPanelSelector).eq(2).should('be.visible');

    // Close and reopen modal
    cy.get(closeModalButtonSelector).click();
    cy.get(modalSelector).should('not.be.visible');
    cy.get(openModalButtonSelector).click();
    cy.get(modalSelector).should('be.visible');

    // Verify the third tab is still active
    cy.get(tabButtonSelector).eq(2).should('have.attr', 'aria-selected', 'true');
    cy.get(tabPanelSelector).eq(2).should('be.visible');
  });

  it('should handle rapid tab switching and maintain the last selected tab', () => {
    // Rapidly switch between tabs
    cy.get(tabButtonSelector).eq(1).click();
    cy.get(tabButtonSelector).eq(2).click();
    cy.get(tabButtonSelector).eq(0).click();
    cy.get(tabButtonSelector).eq(1).click();

    // Verify the last clicked tab is active
    cy.get(tabButtonSelector).eq(1).should('have.attr', 'aria-selected', 'true');
    cy.get(tabPanelSelector).eq(1).should('be.visible');

    // Close and reopen
    cy.get(closeModalButtonSelector).click();
    cy.get(openModalButtonSelector).click();

    // Verify persistence
    cy.get(tabButtonSelector).eq(1).should('have.attr', 'aria-selected', 'true');
    cy.get(tabPanelSelector).eq(1).should('be.visible');
  });

  it('should default to the first tab on initial modal open', () => {
    // Close the modal
    cy.get(closeModalButtonSelector).click();
    cy.get(modalSelector).should('not.be.visible');

    // Clear any stored state
    cy.clearLocalStorage();

    // Reopen the modal
    cy.get(openModalButtonSelector).click();
    cy.get(modalSelector).should('be.visible');

    // Verify the first tab is active by default
    cy.get(tabButtonSelector).eq(0).should('have.attr', 'aria-selected', 'true');
    cy.get(tabPanelSelector).eq(0).should('be.visible');
  });
});
